{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Programs & Pricing — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f6fbf8;--card:#ffffff;--accent:#2b7a5a;--muted:#65746a;--glass:rgba(255,255,255,0.8)}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#183329;background:var(--bg)}
    .site-wrap{min-height:100%;display:flex;flex-direction:column}
    header{background:linear-gradient(180deg,rgba(43,122,90,0.08),transparent 60%),url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="400" height="400"><defs><pattern id="p" width="40" height="40" patternUnits="userSpaceOnUse"><rect width="40" height="40" fill="%23f6fbf8"/><path d="M0 20 L20 0 M-10 30 L10 10 M30 50 L50 30" stroke="%232b7a5a" stroke-opacity="0.06" stroke-width="1"/></pattern></defs><rect width="100%" height="100%" fill="url(%23p)"/></svg>') center/cover no-repeat;padding:28px 20px;border-bottom:1px solid rgba(0,0,0,0.04)}
    .nav{max-width:1100px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;gap:18px}
    .brand{font-weight:700;color:var(--accent)}
    nav a{color:var(--muted);text-decoration:none;margin:0 8px;font-weight:600}
    nav a:hover{color:var(--accent)}
    main{max-width:1100px;margin:24px auto;padding:20px;flex:1}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:22px}
    .card{background:var(--card);border-radius:12px;padding:18px;box-shadow:0 6px 18px rgba(6,22,10,0.06)}
    h1{margin:0 0 6px;font-size:20px}
    p.lead{margin:0 0 12px;color:var(--muted)}
    .mood{display:flex;gap:8px;flex-wrap:wrap}
    .mood button{background:transparent;border:1px solid rgba(24,51,41,0.08);padding:10px 12px;border-radius:10px;cursor:pointer;font-weight:600;color:var(--muted)}
    .mood button.active{background:linear-gradient(90deg,var(--accent),#40a573);color:#fff;border-color:transparent}
    .approach{margin-top:14px;padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(43,122,90,0.04),transparent)}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:10px;background:var(--accent);color:#fff;text-decoration:none;font-weight:700}
    .price-list{display:flex;flex-direction:column;gap:12px}
    .plan{border:1px dashed rgba(43,122,90,0.12);padding:12px;border-radius:10px}
    .plan h3{margin:0 0 8px}
    .meta{font-size:13px;color:var(--muted)}
    .timeline{margin-top:14px}
    .phases{display:flex;gap:8px;align-items:flex-end}
    .phase{flex:1;padding:10px;border-radius:8px;background:linear-gradient(180deg,rgba(0,0,0,0.02),transparent);text-align:center}
    .phase span{display:block;font-weight:700}
    .note{font-size:13px;color:#6a6a6a;margin-top:8px}
    footer{max-width:1100px;margin:28px auto 60px;padding:20px;text-align:center;color:var(--muted)}
    /* small screens */
    @media(min-width:900px){.nav a{margin:0 12px}.grid{grid-template-columns:1fr 420px}}
  </style>
</head>
<body>
  <div class="site-wrap">
    <header>
      <div class="nav">
        <div class="brand">{{BUSINESS_NAME}} — Integrative Events</div>
        <nav aria-label="Primary">
          <a href="index.html">Gatherings</a>
          <a href="services.html">Offerings</a>
          <a href="conditions.html">Health Topics</a>
          <a href="approach.html">How We Work</a>
          <a href="pricing.html">Tuition</a>
          <a href="about.html">About</a>
          <a href="book.html">Reserve</a>
          <a href="contact.html">Connect</a>
        </nav>
      </div>
    </header>

    <main>
      <div class="grid">
        <section class="card">
          <h1>Programs framed as learning journeys, not quick fixes</h1>
          <p class="lead">Choose a pathway below and match it to how you feel today. Programs run as small-group series and one-day intensives; each listing includes the expected pace and a recommended first step.</p>

          <div>
            <label style="font-weight:700;display:block;margin-bottom:8px">Mood-to-Method — pick one</label>
            <div class="mood" role="tablist" aria-label="Mood selector" id="moodSelector">
              <button data-key="drained">Drained</button>
              <button data-key="stressed">Stressed</button>
              <button data-key="curious">Curious</button>
              <button data-key="steady">Steady</button>
            </div>

            <div class="approach" id="approachBox" aria-live="polite">
              <strong id="approachTitle">Recommended approach</strong>
              <p id="approachText" style="margin:6px 0 0;color:var(--muted)">Select how you're feeling to see a tailored entry point and a suggested next step.</p>
              <a href="{{PRIMARY_CTA_URL}}" id="moodCta" class="cta">{{PRIMARY_CTA_LABEL}}</a>
            </div>
          </div>

          <div class="timeline card" style="margin-top:18px">
            <h2 style="margin:0 0 8px;font-size:16px">Three-phase roadmap (example)</h2>
            <div class="phases" aria-hidden="false">
              <div class="phase"><small>Phase 1</small><span id="p1Dur">4–6 weeks</span><small class="meta">Orientation + daily practices</small></div>
              <div class="phase"><small>Phase 2</small><span id="p2Dur">8 weeks</span><small class="meta">Skill building & group sessions</small></div>
              <div class="phase"><small>Phase 3</small><span id="p3Dur">6–12 weeks</span><small class="meta">Integration & personalization</small></div>
            </div>
            <div class="note">This timeline is educational and illustrative only. It complements conversations with your health team; it is not individualized medical treatment.</div>

            <div style="margin-top:10px;display:flex;gap:8px;align-items:center">
              <label style="font-size:13px;color:var(--muted);">Adjust phase lengths</label>
              <input id="p1Input" type="number" value="6" min="1" style="width:64px;padding:6px;border-radius:8px;border:1px solid rgba(0,0,0,0.06)"/>
              <input id="p2Input" type="number" value="8" min="1" style="width:64px;padding:6px;border-radius:8px;border:1px solid rgba(0,0,0,0.06)"/>
              <input id="p3Input" type="number" value="10" min="1" style="width:64px;padding:6px;border-radius:8px;border:1px solid rgba(0,0,0,0.06)"/>
            </div>
          </div>

        </section>

        <aside class="card">
          <h2 style="margin-top:0">Selected offerings</h2>
          <div class="price-list">
            <div class="plan">
              <h3>Foundational Series — 6 weeks</h3>
              <div class="meta">Small cohort • Weekly live sessions • Practical toolkits</div>
              <p style="margin:8px 0 0;color:var(--muted)">A paced learning track for rebuilding daily structure and gentle habits.</p>
              <div style="margin-top:8px;font-weight:700">$420 per seat</div>
            </div>

            <div class="plan">
              <h3>Resync Intensive — weekend</h3>
              <div class="meta">One-day lab • Focused practices • Take-home plan</div>
              <p style="margin:8px 0 0;color:var(--muted)">A concentrated day to recalibrate routines and reset priorities.</p>
              <div style="margin-top:8px;font-weight:700">$180 per person</div>
            </div>

            <div class="plan">
              <h3>Continuity Cohort — ongoing</h3>
              <div class="meta">Monthly check-ins • Peer learning • Resources</div>
              <p style="margin:8px 0 0;color:var(--muted)">Sustained support for people who want a long-term learning container.</p>
              <div style="margin-top:8px;font-weight:700">$60 / month</div>
            </div>
          </div>

          <div style="margin-top:14px">
            <strong>Refund & health note</strong>
            <p class="note">Because these are educational sessions, we prioritize clarity about expectations. If you have medical questions, consult your licensed clinician; these programs are not substitutes for clinical care.</p>
          </div>

          <div style="margin-top:12px">
            <a id="reserveNow" class="cta" href="{{PRIMARY_CTA_URL}}">Book a space</a>
          </div>
        </aside>
      </div>
    </main>

    <footer>
      <div>Questions? Call {{PHONE}} or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      <div style="margin-top:8px;font-size:13px">Serving {{CITY}}, {{STATE}} — schedule and seats vary by series.</div>
    </footer>
  </div>

  <script>
    (function(){
      const moods = {
        drained:{title:'Short resets + low-effort moves',text:'Gentle, brief practices and a simplified day plan reduce decision fatigue. Recommended: Resync Intensive or a 2-week micro-track.',cta:'Reserve a calming spot'},
        stressed:{title:'Structure-first: predictable steps',text:'Clear sequences and cue-based habits help lower reactivity. Recommended: Foundational Series with weekly rituals and checklists.',cta:'Join a structured series'},
        curious:{title:'Explore & experiment',text:'Try a focused intensive or sample session to collect what helps you. Recommended: Resync Intensive or a single workshop.',cta:'Try an intensive'},
        steady:{title:'Deepen & integrate',text:'Layer practices and personalize routines for longer-term change. Recommended: Continuity Cohort with monthly refinement.',cta:'Join the continuity cohort'}
      };

      const selector = document.getElementById('moodSelector');
      const buttons = selector.querySelectorAll('button');
      const approachTitle = document.getElementById('approachTitle');
      const approachText = document.getElementById('approachText');
      const moodCta = document.getElementById('moodCta');
      const reserveNow = document.getElementById('reserveNow');

      function setMood(key,btn){
        buttons.forEach(b=>b.classList.remove('active'));
        if(btn) btn.classList.add('active');
        const data = moods[key] || {title:'Recommended approach',text:'Select how you feel to see a suggested entry point.',cta:'Get started'};
        approachTitle.textContent = data.title;
        approachText.textContent = data.text;
        moodCta.textContent = data.cta + ' — ' + '{{PRIMARY_CTA_LABEL}}';
        moodCta.href = '{{PRIMARY_CTA_URL}}';
        reserveNow.textContent = data.cta;
        reserveNow.href = '{{PRIMARY_CTA_URL}}';
      }

      selector.addEventListener('click',function(e){
        if(e.target.tagName.toLowerCase()!== 'button') return;
        const key = e.target.getAttribute('data-key');
        setMood(key,e.target);
      });

      // initialize default
      setMood('curious', selector.querySelector('[data-key=curious]'));

      // timeline inputs
      function updateTimeline(){
        const p1 = parseInt(document.getElementById('p1Input').value,10)||1;
        const p2 = parseInt(document.getElementById('p2Input').value,10)||1;
        const p3 = parseInt(document.getElementById('p3Input').value,10)||1;
        document.getElementById('p1Dur').textContent = p1 + ' weeks';
        document.getElementById('p2Dur').textContent = p2 + ' weeks';
        document.getElementById('p3Dur').textContent = p3 + ' weeks';
      }
      ['p1Input','p2Input','p3Input'].forEach(id=>document.getElementById(id).addEventListener('input',updateTimeline));
      updateTimeline();
    })();
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fffefb;--accent:#1f7a5a;--muted:#556457;--card:#ffffff}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;color:#15302a;background:var(--bg)}
    header{padding:18px 20px;border-bottom:1px solid rgba(0,0,0,0.04);background:linear-gradient(0deg,rgba(31,122,90,0.03),transparent)}
    .nav{max-width:1000px;margin:0 auto;display:flex;align-items:center;justify-content:space-between}
    .brand{font-weight:800;color:var(--accent)}
    nav a{margin-left:10px;color:var(--muted);text-decoration:none;font-weight:600}
    main{max-width:1000px;margin:26px auto;padding:20px}
    .hero{display:flex;gap:18px;align-items:flex-start}
    .intro{flex:1}
    .card{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 8px 20px rgba(6,22,10,0.04)}
    h1{margin:0 0 8px}
    p.lead{margin:0 0 12px;color:var(--muted)}
    .values{display:flex;gap:10px;margin-top:12px}
    .value{flex:1;padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(31,122,90,0.04),transparent)}
    .mood-mini{margin-top:12px}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:10px;background:var(--accent);color:#fff;text-decoration:none;font-weight:700}
    .timeline{margin-top:16px}
    .phase-list{display:flex;gap:8px}
    .phase{flex:1;padding:10px;border-radius:8px;background:#f6faf7;text-align:center}
    .disclaimer{font-size:13px;color:#6c6c6c;margin-top:10px}
  </style>
</head>
<body>
  <header>
    <div class="nav">
      <div class="brand">{{BUSINESS_NAME}} • Integrative Events</div>
      <nav>
        <a href="index.html">Gather</a>
        <a href="services.html">Programs</a>
        <a href="approach.html">Method</a>
        <a href="pricing.html">Tuition</a>
        <a href="book.html">Reserve</a>
      </nav>
    </div>
  </header>

  <main>
    <div class="hero">
      <div class="intro card">
        <h1>Who we are</h1>
        <p class="lead">We design short, practical learning experiences that help people move from intention to steady routine. Our work blends evidence-informed habits, group learning, and individualized adaptation.</p>

        <div class="values">
          <div class="value"><strong>Small groups</strong><div style="color:var(--muted);margin-top:6px">Intentional cohorts to practice and reflect together.</div></div>
          <div class="value"><strong>Action-focused</strong><div style="color:var(--muted);margin-top:6px">Tools you can apply in the next day, week, and month.</div></div>
          <div class="value"><strong>Adaptable</strong><div style="color:var(--muted);margin-top:6px">Adjustable timelines so you can match progress to life.</div></div>
        </div>

        <div class="mood-mini" style="margin-top:14px">
          <label style="font-weight:700">Mood-to-Method (quick)</label>
          <div style="display:flex;gap:8px;margin-top:8px" id="miniMood">
            <button data-key="drained" style="padding:8px 10px;border-radius:8px;border:1px solid rgba(0,0,0,0.06);background:#fff;cursor:pointer">Drained</button>
            <button data-key="stressed" style="padding:8px 10px;border-radius:8px;border:1px solid rgba(0,0,0,0.06);background:#fff;cursor:pointer">Stressed</button>
            <button data-key="curious" style="padding:8px 10px;border-radius:8px;border:1px solid rgba(0,0,0,0.06);background:#fff;cursor:pointer">Curious</button>
          </div>
          <div id="miniSuggestion" style="margin-top:10px;color:var(--muted)">Pick how you feel to see a short suggestion.</div>
        </div>

        <a id="aboutCta" class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>

      <aside style="width:320px">
        <div class="card">
          <h3 style="margin-top:0">Team snapshot</h3>
          <p style="margin:6px 0;color:var(--muted)">Our facilitators are trained with clinical awareness and group-teaching craft. We pair practical skills with attention to safety and limits.</p>

          <div style="margin-top:10px">
            <h4 style="margin:6px 0">Three-phase learning pathway</h4>
            <div class="timeline">
              <div class="phase-list">
                <div class="phase">Phase 1<br><small class="meta">Orientation</small></div>
                <div class="phase">Phase 2<br><small class="meta">Skill practice</small></div>
                <div class="phase">Phase 3<br><small class="meta">Integration</small></div>
              </div>
              <div class="disclaimer">Educational format; not a clinical treatment plan. Always consult your healthcare team for personal medical decisions.</div>
            </div>
          </div>
        </div>

        <div style="height:12px"></div>
        <div class="card">
          <h4 style="margin:6px 0">Contact</h4>
          <div style="color:var(--muted)">Phone: {{PHONE}}<br>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
        </div>
      </aside>
    </div>
  </main>

  <script>
    (function(){
      const moods = {
        drained:'Start with brief, low-friction practices: short cues and an easy bedtime routine. Consider a weekend reset to reduce decision load.',
        stressed:'Structure incoming days with a predictable morning and evening sequence. A paced series can help make responses habitual.',
        curious:'Try a one-day intensive or sample session to discover what resonates before committing to a longer path.'
      };
      document.getElementById('miniMood').addEventListener('click',function(e){
        if(e.target.tagName!=='BUTTON') return;
        const k = e.target.getAttribute('data-key');
        document.getElementById('miniSuggestion').textContent = moods[k] || '';
        // update CTA to reflect prompt
        document.getElementById('aboutCta').textContent = (k==='curious') ? 'Try a session' : '{{PRIMARY_CTA_LABEL}}';
      });
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f5fff8;--accent:#237a5a;--muted:#5a6b63}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:var(--bg);color:#123529}
    .wrap{max-width:900px;margin:28px auto;padding:18px}
    header{display:flex;justify-content:space-between;align-items:center}
    header a{color:var(--muted);text-decoration:none;margin-left:10px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:16px;margin-top:18px}
    .card{background:#fff;padding:16px;border-radius:12px;box-shadow:0 10px 30px rgba(6,22,10,0.04)}
    h1{margin:0 0 6px}
    .form-row{display:flex;flex-direction:column;margin-bottom:10px}
    label{font-weight:700;font-size:13px;margin-bottom:6px}
    input,select,textarea{padding:10px;border-radius:8px;border:1px solid rgba(0,0,0,0.06);font-size:14px}
    .mood-block{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}
    .mood-block button{padding:8px 10px;border-radius:8px;border:1px solid rgba(0,0,0,0.06);background:#fff;cursor:pointer}
    .submit{margin-top:12px;padding:10px 12px;border-radius:10px;background:var(--accent);color:#fff;text-decoration:none;border:none;font-weight:700}
    .timeline{margin-top:12px;padding:10px;border-radius:10px;background:linear-gradient(180deg,rgba(35,122,90,0.04),transparent)}
    .small{font-size:13px;color:var(--muted)}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div style="font-weight:800;color:var(--accent)">{{BUSINESS_NAME}} — Reserve</div>
      <nav>
        <a href="index.html">Gather</a>
        <a href="services.html">Programs</a>
        <a href="pricing.html">Tuition</a>
      </nav>
    </header>

    <div class="grid">
      <section class="card">
        <h1>Reserve your place</h1>
        <p class="small">Tell us a few basics and select a session. We’ll follow up with availability and a short onboarding note.</p>

        <div style="margin-top:12px">
          <div class="form-row">
            <label for="name">Full name</label>
            <input id="name" placeholder="Your name" />
          </div>
          <div class="form-row">
            <label for="email">Email</label>
            <input id="email" placeholder="you@example.com" />
          </div>

          <div class="form-row">
            <label for="program">Select program</label>
            <select id="program">
              <option value="foundations">Foundational Series — 6 weeks</option>
              <option value="intensive">Resync Intensive — weekend</option>
              <option value="cohort">Continuity Cohort — monthly</option>
            </select>
          </div>

          <div class="form-row">
            <label>How are you feeling right now?</label>
            <div class="mood-block" id="bookMood">
              <button data-key="drained">Drained</button>
              <button data-key="stressed">Stressed</button>
              <button data-key="curious">Curious</button>
              <button data-key="steady">Steady</button>
            </div>
          </div>

          <div class="form-row">
            <label for="notes">Notes (optional)</label>
            <textarea id="notes" rows="3" placeholder="Any specifics to share about your goals or limits"></textarea>
          </div>

          <button class="submit" id="submitBtn">Complete reservation</button>
          <div id="bookConfirm" class="small" style="margin-top:8px;color:var(--muted)"></div>
        </div>

        <div class="timeline" aria-live="polite">
          <strong>Expected progression (example)</strong>
          <div style="margin-top:8px" id="bookTimeline">
            Phase 1: Intro & short practices — 4–6 weeks<br>
            Phase 2: Consolidation — 8 weeks<br>
            Phase 3: Integration — variable
          </div>
          <div class="small" style="margin-top:8px;color:#5f6f68">Reminder: the sequence is an educational roadmap. It is not medical advice. If you have health concerns, consult a licensed clinician before participating.</div>
        </div>
      </section>

      <aside class="card">
        <h3 style="margin-top:0">Quick pricing</h3>
        <div style="margin-top:8px">Foundational Series — $420 per seat</div>
        <div style="margin-top:6px">Resync Intensive — $180 per person</div>
        <div style="margin-top:6px">Continuity Cohort — $60/month</div>

        <div style="margin-top:12px">
          <strong>Need help choosing?</strong>
          <p class="small">Use the mood selector above to pick a starting point — we’ll include a recommended session in the reply.</p>
        </div>

        <div style="margin-top:12px">
          <a href="mailto:{{EMAIL}}" style="display:inline-block;padding:8px 10px;border-radius:8px;background:var(--accent);color:#fff;text-decoration:none">Email to ask</a>
        </div>
      </aside>
    </div>

  </div>

  <script>
    (function(){
      const moodMap = {
        drained:{suggest:'Resync Intensive',note:'Short, focused reset with low daily friction.'},
        stressed:{suggest:'Foundational Series',note:'A steady sequence to build predictable habits.'},
        curious:{suggest:'Resync Intensive',note:'Try a single session to see what lands.'},
        steady:{suggest:'Continuity Cohort',note:'Long-term refinement and monthly check-ins.'}
      };

      const moodEl = document.getElementById('bookMood');
      const submitBtn = document.getElementById('submitBtn');
      const confirm = document.getElementById('bookConfirm');
      let selectedMood = 'curious';

      moodEl.addEventListener('click',function(e){
        if(e.target.tagName!=='BUTTON') return;
        const key = e.target.getAttribute('data-key');
        selectedMood = key;
        // visual
        moodEl.querySelectorAll('button').forEach(b=>b.style.boxShadow='none');
        e.target.style.boxShadow='inset 0 0 0 2px rgba(35,122,90,0.12)';
      });

      submitBtn.addEventListener('click',function(){
        const name = document.getElementById('name').value.trim();
        const email = document.getElementById('email').value.trim();
        const program = document.getElementById('program').value;
        if(!name || !email){
          confirm.textContent = 'Please provide your name and email to reserve a spot.';
          return;
        }
        const suggestion = moodMap[selectedMood] ? moodMap[selectedMood].suggest : 'a suitable session';
        confirm.textContent = 'Thanks, ' + name + '. We received your request. Based on how you said you feel, we note: ' + suggestion + '. You will receive a confirmation at ' + email + ' with next steps.';
        // simulate sending data to server (local-only)
        submitBtn.textContent = 'Requested';
        submitBtn.disabled = true;
      });

